SZGame3D.runProject(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame3D.restart());
  // Ao iniciar
  const cena = SZGame3D.createFullscreenScene("#bfe6f2");
  SZGame3D.frameScene(cena, 18, 5, 10);
  const chao = SZGame3D.createModelFile(cena, "chao-sua-ilha", 19);
  SZGame3D.setPosition(chao, 0, -0.48, 0);
  const personagem = SZGame3D.createModelFile(cena, "aventureiro", 1.66);
  SZGame3D.setPosition(personagem, -4, 0.8, 0);
  const item = SZGame3D.createModelFile(cena, "concha-vieira", 0.8);
  SZGame3D.setPosition(item, -1.5, 0.3, -1.5);
  const morador = SZGame3D.createModelFile(cena, "nico", 2);
  SZGame3D.setPosition(morador, 3, 0.72, 0.5);
  SZGame3D.walkArea(personagem, -8, 8, -4.5, 4.5);
  SZGame3D.walkAnimations(personagem, "parado", "andando");
  let temItem = false;
  let entregue = false;
  let pediu = false;
  let aviso = "Ache a concha e leve até o Nico.";
  SZGame3D.hudText("bottom-center", "Setas ou WASD: andar. R: recomeçar.");
  // Quando acontecer
  SZGame3D.onKey("KeyR", () => {
    SZGame3D.restart();
  });
  SZGame3D.onTouch(personagem, item, () => {
    SZGame3D.setVisible(item, "hide");
    temItem = true;
    aviso = "Você pegou a concha. Agora leve até o Nico.";
  });
  SZGame3D.onTouch(personagem, morador, () => {
    if (!entregue) {
      if (temItem) {
        entregue = true;
        SZGame3D.playAnimation(morador, "feliz", "uma-vez");
        aviso = "O Nico ficou feliz com a concha.";
      } else {
        pediu = true;
        aviso = "O Nico pede a concha. Ela está na areia.";
      }
    }
  });
  // Enquanto estiver rodando
  SZGame3D.animate(cena, () => {
    SZGame3D.topDown(personagem, 4);
    SZGame3D.hudText("top-center", aviso);
  });
});
